1120	\begin{theorem}[The Sigma Picard functor is a big-etale sheaf]
1121	  \label{thm:pic0SigmaFunctor_isEtaleSheaf}
1122	  \uses{def:pic0SigmaFunctor, thm:pic0SigmaFunctor_isSheaf,
1123	    def:admissibleAbelEtaleSheafMap}
1124	  \notready
1125	  The Sigma-extension of \(\mathrm{pic}^0\) satisfies descent for the big-etale topology,
1126	  and its universe-raised sheaf is canonically isomorphic to the sheafification in
1127	  Definition~\ref{def:admissibleAbelEtaleSheafMap}.
1128	\end{theorem}
1129	
1130	\begin{theorem}[Etale-local surjectivity of the admissible Abel map]
1131	  \label{thm:admissibleAbel_etaleLocallySurjective}
1132	  \lean{AlgebraicGeometry.isLocallySurjective_abelSigmaChartAffAdmissible}
1133	  \uses{def:admissibleAbelMap, def:admissibleAbelEtaleSheafMap}
1134	  \leanok
1135	  The concrete admissible Abel transformation is locally surjective for the big-etale
1136	  topology. Equivalently, every degree-zero Picard class lifts to an admissible divisor
1137	  family after an etale cover of the test scheme.
1138	  \source{kleiman-picard}
1139	\end{theorem}
1140	
1141	\begin{theorem}[The sheafified Abel map is the coequalizer of its kernel pair]
1142	  \label{thm:admissibleAbel_etaleCoequalizer}
1143	  \lean{AlgebraicGeometry.admissibleAbelEtaleSheafMap_isLocallySurjective,
1144	    AlgebraicGeometry.admissibleAbelEtaleTargetCoequalizer}
1145	  \uses{def:admissibleAbelEtaleSheafMap,
1146	    thm:admissibleAbel_etaleLocallySurjective}
1147	  \leanok
1148	  Local surjectivity makes the sheafified Abel map a regular epimorphism in the category of
1149	  type-valued big-etale sheaves. Hence it is the coequalizer of its pullback kernel pair.
1150	\end{theorem}
1151	
1152	\begin{theorem}[The concrete Abel kernel pair is representable]
1153	  \label{thm:admissibleAbelKernelPair_representable}
1154	  \uses{thm:admissibleAbel_etaleKernel, thm:admissibleAbel_fibreRank,
1155	    thm:admissibleDivisorSource_projectLocal}
1156	  \notready
1157	  Construct a scheme \(R\) representing the concrete kernel relation on
1158	  \(D_{\mathrm{adm}}\), identify it with the fibre product over the Picard sheaf, and prove
1159	  that the first projection \(R \to D_{\mathrm{adm}}\) is smooth and proper.
1160	  \source{kleiman-picard}
1161	\end{theorem}
1162	
1163	\begin{theorem}[The Altman--Kleiman effective quotient]
1164	  \label{thm:admissibleAbel_effectiveQuotient}
1165	  \uses{thm:admissibleDivisorSource_projectLocal,
1166	    thm:admissibleAbelKernelPair_representable}
1167	  \notready
1168	  Apply the flat-proper equivalence-relation theorem to construct a scheme
1169	  \(Q = D_{\mathrm{adm}}/R\) over \(\Spec k\), with quotient map
1170	  \(D_{\mathrm{adm}} \to Q\), and identify \(R\) with
1171	  \(D_{\mathrm{adm}} \times_Q D_{\mathrm{adm}}\). This is a construction of the concrete
1172	  quotient, not a theorem with quotient data as a hypothesis.
1173	  \source{kleiman-picard}
1174	\end{theorem}
1175	
1176	\begin{theorem}[Yoneda identification of the quotient]
1177	  \label{thm:admissibleAbel_quotientYoneda}
1178	  \uses{thm:pic0SigmaFunctor_isEtaleSheaf,
1179	    thm:admissibleAbel_etaleCoequalizer,
1180	    thm:admissibleAbel_effectiveQuotient,
1181	    thm:admissibleAbel_etaleKernel}
1182	  \notready
1183	  The Yoneda sheaf of \(Q\) and the degree-zero Picard Sigma functor are coequalizers of
1184	  the same represented kernel pair. The induced isomorphism is compatible with the
1185	  structure maps to \(\Spec k\), and therefore descends from the Sigma-extension to
1186	  \(\mathrm{pic}^0_{\mathrm{Set}}(C)\) on the slice.
1187	  \source{kleiman-picard}
1188	\end{theorem}
1189	
1190	\begin{definition}[The admissible Abel quotient representer]
1191	  \label{def:pic0AdmissibleAbelQuotientRepresenter}
1192	  \uses{def:admissibleDivisorRepresentation, thm:admissibleAbel_quotientYoneda,
1193	    thm:representableBy_overSlice}
1194	  \notready
1195	  The direct endpoint is
1196	  \[
1197	    \operatorname{pic0AdmissibleAbelQuotientRepresenter}(C)
1198	      : \sum_{Q : \Over(\Spec k)}
1199	          \mathrm{RepresentableBy}\bigl(\mathrm{pic0TypeFunctor}(C),Q\bigr).
1200	  \]
1201	  Its body chooses the admissible datum internally, directly consumes
1202	  \(\operatorname{divFunctorAff\_admissible\_representableBy}\), constructs the effective
1203	  quotient above, and returns its Yoneda comparison. It has no representability,
1204	  local-surjectivity, kernel-pair, rational-point, or quotient-data binder.
1205	\end{definition}
